#!/usr/bin/env python3
"""Build ephemeris_tables.txt, the coefficient file shared by the Kotlin and Swift engines.

Sources (download them yourself; they are not kept in the repo):
  * VSOP87D (Bretagnon & Francou 1988), heliocentric spherical coordinates referred to the
    dynamical ecliptic and equinox OF DATE: https://ftp.imcce.fr/pub/ephem/planets/vsop87/
    files VSOP87D.mer .ven .ear .mar .jup .sat .ura .nep
  * Meeus, Astronomical Algorithms 2nd ed., tables 47.A/47.B (Moon, ELP-2000/82 truncation) and
    37.A (Pluto), as transcribed in github.com/soniakeys/meeus (MIT) v3/moonposition/moonposition.go
    and v3/pluto/pluto.go.

VSOP87 terms are kept when |A| * tau_max**power >= threshold, tau_max = 0.11 Julian millennia
(1890-2110). Thresholds are chosen so the truncation error is a few arcseconds at worst - far
inside the 0.05 deg (180") accuracy budget - while keeping the file small enough to ship.

Usage:
    python3 make_ephemeris_tables.py --vsop DIR --meeus DIR --out PATH
"""

from __future__ import annotations

import argparse
import re
import sys

PLANETS = [("MERCURY", "mer"), ("VENUS", "ven"), ("EARTH", "ear"), ("MARS", "mar"),
           ("JUPITER", "jup"), ("SATURN", "sat"), ("URANUS", "ura"), ("NEPTUNE", "nep")]
VARS = {1: "L", 2: "B", 3: "R"}
TAU_MAX = 0.11
# Per-variable thresholds: radians for L and B, AU for R (scaled by the mean distance so the
# corresponding angular error seen from Earth stays ~1e-7 rad for every planet).
THRESH_ANGLE = 2.0e-7
THRESH_R_REL = 2.0e-7
MEAN_A = {"MERCURY": 0.387, "VENUS": 0.723, "EARTH": 1.0, "MARS": 1.524, "JUPITER": 5.203,
          "SATURN": 9.537, "URANUS": 19.19, "NEPTUNE": 30.07}

HEADER = re.compile(r"VARIABLE (\d) \(LBR\)\s+\*T\*\*(\d)\s+(\d+) TERMS?")


def read_vsop(path: str):
    """Yield (var, power, [(A, B, C), ...]) series from one VSOP87D file."""
    series = []
    current = None
    with open(path, encoding="ascii") as fh:
        for line in fh:
            m = HEADER.search(line)
            if m:
                current = (int(m.group(1)), int(m.group(2)), [], int(m.group(3)))
                series.append(current)
                continue
            if not line.strip():
                continue
            # Fixed-format record: the last three numbers are A, B, C.
            parts = line.split()
            a, b, c = float(parts[-3]), float(parts[-2]), float(parts[-1])
            current[2].append((a, b, c))
    for var, power, terms, expected in series:
        if len(terms) != expected:
            raise SystemExit(f"{path}: var {var} T^{power} has {len(terms)} terms, header says {expected}")
    return series


def parse_go_rows(source: str, var_name: str, width: int):
    """Extract the numeric rows of a Go slice/array literal named var_name."""
    start = source.index(f"var {var_name} =")
    end = source.index("\n}\n", start)
    rows = []
    number = r"-?(?:\d+\.?\d*|\.\d+)"
    row_re = re.compile(r"\{\s*(" + number + r"(?:\s*,\s*" + number + r")*)\s*,?\s*\}")
    for m in row_re.finditer(source, start, end):
        nums = [x.strip() for x in m.group(1).split(",")]
        if len(nums) == width:
            rows.append([float(x) for x in nums])
    return rows


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--vsop", required=True)
    ap.add_argument("--meeus", required=True)
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    out = []
    out.append("# Conjunction ephemeris coefficient tables. GENERATED by testdata/tools/make_ephemeris_tables.py")
    out.append("# Do not edit by hand. Format: a section header line, then that many data lines.")
    out.append("#   VSOP <BODY> <L|B|R> <power> <n>  then n lines 'A B C'  (term = A*cos(B + C*tau), tau = Julian millennia TT from J2000)")
    out.append("#   MOON_LR <n>  then 'D M Mp F sumL sumR'  (Meeus table 47.A; sumL 1e-6 deg, sumR 1e-3 km)")
    out.append("#   MOON_B <n>   then 'D M Mp F sumB'       (Meeus table 47.B; 1e-6 deg)")
    out.append("#   PLUTO <n>    then 'i j k lA lB bA bB rA rB' (Meeus table 37.A; deg, deg, AU)")
    out.append(f"# VSOP87D truncation: |A|*{TAU_MAX}^power >= {THRESH_ANGLE} rad (L,B) or {THRESH_R_REL}*a AU (R)")
    total = 0
    for body, ext in PLANETS:
        for var, power, terms in ((v, p, t) for v, p, t, _ in read_vsop(f"{args.vsop}/VSOP87D.{ext}")):
            thr = THRESH_ANGLE if var in (1, 2) else THRESH_R_REL * MEAN_A[body]
            kept = [t for t in terms if abs(t[0]) * TAU_MAX ** power >= thr]
            if not kept:
                continue
            out.append(f"VSOP {body} {VARS[var]} {power} {len(kept)}")
            for a, b, c in kept:
                out.append(f"{a!r} {b!r} {c!r}")
            total += len(kept)

    moon_src = open(f"{args.meeus}/moonposition.go", encoding="utf-8").read()
    ta = parse_go_rows(moon_src, "ta", 6)
    tb = parse_go_rows(moon_src, "tb", 5)
    if len(ta) != 60 or len(tb) != 60:
        raise SystemExit(f"expected 60 rows in Meeus 47.A/47.B, got {len(ta)}/{len(tb)}")
    out.append(f"MOON_LR {len(ta)}")
    out.extend(" ".join(f"{int(x)}" for x in row) for row in ta)
    out.append(f"MOON_B {len(tb)}")
    out.extend(" ".join(f"{int(x)}" for x in row) for row in tb)

    pluto_src = open(f"{args.meeus}/pluto.go", encoding="utf-8").read()
    t37 = parse_go_rows(pluto_src, "t37", 9)
    if len(t37) != 43:
        raise SystemExit(f"expected 43 rows in Meeus 37.A, got {len(t37)}")
    out.append(f"PLUTO {len(t37)}")
    out.extend(" ".join(repr(x) if not float(x).is_integer() else str(int(x)) for x in row) for row in t37)

    with open(args.out, "w", encoding="ascii") as fh:
        fh.write("\n".join(out) + "\n")
    print(f"wrote {args.out}: {total} VSOP terms, {len(ta)}+{len(tb)} Moon terms, {len(t37)} Pluto terms")
    return 0


if __name__ == "__main__":
    sys.exit(main())
